/* ============================================================
   闪卡共享数据层（卡池 + 当日队列状态）
   单卡模式 / 列表模式 共用同一份队列与标记，双模式进度一致
   规则来源：闪卡功能规则.md §5 双模式数据一致性
   ============================================================ */
var FLASH_KEY = 'flashCardState_v2';
var CONFIG_KEY = 'flashCardConfig_v1';

/* ------------------------------------------------------------
   学生个性化配置：每日卡片数量 + 各章节题型比例
   weights = { 章节名: 百分比 }，缺省章节 / 未配置 → 各章均分
   ------------------------------------------------------------ */
var DEFAULT_CONFIG = { dailyCount: 350, weights: {} };

function loadConfig() {
  try {
    var raw = localStorage.getItem(CONFIG_KEY);
    if (raw) {
      var c = JSON.parse(raw);
      if (c && c.dailyCount) return { dailyCount: c.dailyCount, weights: c.weights || {} };
    }
  } catch (e) {}
  return { dailyCount: DEFAULT_CONFIG.dailyCount, weights: {} };
}

function saveConfig(cfg) {
  try { localStorage.setItem(CONFIG_KEY, JSON.stringify(cfg)); } catch (e) {}
  /* 当天尚未开始时重建队列，让新配置立即生效；已开始则保留进度，次日生效 */
  var s = null;
  try {
    var raw = localStorage.getItem(FLASH_KEY);
    if (raw) s = JSON.parse(raw);
  } catch (e) {}
  if (!s || s.date !== todayStr() || calcStats(s).done === 0) saveState(newState());
}

/* 实际每日配额 = min(配置值, 卡池可用卡数)（演示卡池 12 张时自动收缩） */
function getDailyCount() {
  var cfg = loadConfig();
  var n = cfg.dailyCount || DEFAULT_CONFIG.dailyCount;
  return Math.max(1, Math.min(n, CARDS.length));
}

/* ------------------------------------------------------------
   演示卡池（12 张，覆盖 10 章真实考点，统一为填空题形式）
   forgotCount = 跨天累计「未记住」次数（演示预设值）
   ≥3 自动打标「顽固卡」，每天必现（规则 §2.1）
   ------------------------------------------------------------ */
