/* ------------------------------------------------------------
   工具
   ------------------------------------------------------------ */
function todayStr() {
  var d = new Date();
  var m = ('0' + (d.getMonth() + 1)).slice(-2);
  var day = ('0' + d.getDate()).slice(-2);
  return d.getFullYear() + '-' + m + '-' + day;
}

function shuffle(arr) {
  for (var i = arr.length - 1; i > 0; i--) {
    var j = Math.floor(Math.random() * (i + 1));
    var t = arr[i]; arr[i] = arr[j]; arr[j] = t;
  }
  return arr;
}

/* HTML 转义 */
function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;')
    .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

/* 把填空题干中的 ____ 渲染为视觉空位（fill 为真时填入答案高亮） */
function clozeHtml(text, fill) {
  var blankSpan = '<span class="cloze-blank"></span>';
  var fillSpan = fill ? '<span class="cloze-fill">' + esc(fill) + '</span>' : blankSpan;
  return esc(text).replace(/_{2,}/g, fillSpan);
}

/* ------------------------------------------------------------
   URL 参数读取
   ------------------------------------------------------------ */
function getParam(name) {
  var m = new RegExp('[?&]' + name + '=([^&]*)').exec(window.location.search);
  return m ? decodeURIComponent(m[1]) : '';
}

/* 判断卡片是否匹配章节/题型过滤条件 */
function matchesFilter(card, filter) {
  if (!filter) return true;
  if (filter.chapter && card.chapter !== filter.chapter) return false;
  if (filter.sub && card.sub !== filter.sub) return false;
  if (filter.topic && card.topic !== filter.topic) return false;
  if (filter.point && card.point !== filter.point) return false;
  return true;
}

/* 从 URL 解析过滤条件 */
function filterFromUrl() {
  return {
    chapter: getParam('chapter') || '',
    sub: getParam('sub') || '',
    topic: getParam('topic') || '',
    point: getParam('point') || ''
  };
}

/* 过滤状态队列（返回新对象，不改动原状态） */
function filterState(state, filter) {
  if (!filter || (!filter.chapter && !filter.sub && !filter.topic && !filter.point)) {
    return state;
  }
  var q = [];
  for (var i = 0; i < state.queue.length; i++) {
    if (matchesFilter(state.queue[i], filter)) q.push(state.queue[i]);
  }
  return { date: state.date, quota: q.length, queue: q, marked: state.marked };
}

/* ------------------------------------------------------------
   队列生成（规则 §1.2）
   优先级：顽固卡（累计未记住 ≥3，每天必现）→ 剩余配额按题型比例抽新卡 → 卡量不足兜底补齐
   比例来源：学生配置 weights（章节 → 百分比），未配置章节均分
   配额：min(配置 dailyCount, 卡池可用卡数)
   ------------------------------------------------------------ */
function buildQueue() {
  var daily = getDailyCount();
  var cfg = loadConfig();
  var weights = cfg.weights || {};

  /* 按章节分组 */
  var groups = {}, order = [];
  CARDS.forEach(function(c, i) {
    if (!groups[c.chapter]) { groups[c.chapter] = []; order.push(c.chapter); }
    groups[c.chapter].push(i);
  });

  var queue = [];
  function pushCard(i) {
    var c = CARDS[i];
    queue.push({
      key: 'c' + i + '#1', id: 'c' + i,
      chapter: c.chapter, sub: c.sub, topic: c.topic, point: c.point,
      question: c.question, answer: c.answer, analysis: c.analysis,
      forgotCount: c.forgotCount || 0, round: 1
    });
  }
  function isUsed(i) {
    var id = 'c' + i;
    for (var q = 0; q < queue.length; q++) if (queue[q].id === id) return true;
    return false;
  }

  /* 第 1 优先级：复习卡每天必现 = 未记住卡（累计 forgotCount≥1）+ 顽固卡（≥3，属未记住子集） */
  order.forEach(function(ch) {
    groups[ch].forEach(function(i) {
      if ((CARDS[i].forgotCount || 0) >= 1) pushCard(i);
    });
  });

  /* 第 2 优先级：每章配额扣减该章复习卡后，余量抽新卡（扣减式）
     该章应得 = 每日数量 × 该章比例；该章新卡 = max(0, 该章应得 − 该章复习卡数) */
  var remaining = daily - queue.length;
  if (remaining > 0) {
    var totalW = 0;
    order.forEach(function(ch) {
      var w = weights[ch];
      if (typeof w === 'number' && isFinite(w) && w > 0) totalW += w;
    });
    var quotaMap = {};
    order.forEach(function(ch) {
      var w = weights[ch] || 0;
      quotaMap[ch] = totalW > 0 ? Math.round(daily * w / totalW) : Math.round(daily / order.length);
    });
    var usedCh = {};
    queue.forEach(function(x) { usedCh[x.chapter] = (usedCh[x.chapter] || 0) + 1; });
    order.forEach(function(ch) {
      if (remaining <= 0) return;
      var fresh = Math.max(0, quotaMap[ch] - (usedCh[ch] || 0)); /* 扣已入队复习卡 */
      var pool = shuffle(groups[ch].filter(function(i) { return !isUsed(i); }));
      fresh = Math.min(fresh, pool.length);
      for (var k = 0; k < fresh; k++) { pushCard(pool[k]); remaining--; }
    });
  }

  /* 第 3 优先级：配额兜底（比例不足 / 章节卡量不足时，用剩余卡补齐） */
  if (queue.length < daily) {
    var rest = [];
    CARDS.forEach(function(c, i) { if (!isUsed(i)) rest.push(i); });
    rest = shuffle(rest);
    for (var r = 0; r < rest.length && queue.length < daily; r++) pushCard(rest[r]);
  }

  return queue;
}

/* 全卡池队列：把 CARDS 全部转为队列对象（不抽样、不按配额裁剪）
   用于单卡模式从首页章节/考点跳入时，保证任意考点都能刷到全部题目 */
function buildFullQueue() {
  var queue = [];
  for (var i = 0; i < CARDS.length; i++) {
    var c = CARDS[i];
    queue.push({
      key: 'c' + i + '#1', id: 'c' + i,
      chapter: c.chapter, sub: c.sub, topic: c.topic, point: c.point,
      question: c.question, answer: c.answer, analysis: c.analysis,
      forgotCount: c.forgotCount || 0, round: 1
    });
  }
  return queue;
}

/* 生成全新当天状态（跨天累计的 forgotCount 保留在卡片上） */
function newState() {
  return { date: todayStr(), quota: getDailyCount(), queue: shuffle(buildQueue()), marked: {}, markedTime: {} };
}

/* ------------------------------------------------------------
   状态读写（localStorage，按天隔离）
   ------------------------------------------------------------ */
function loadState() {
  try {
    var raw = localStorage.getItem(FLASH_KEY);
    if (raw) {
      var s = JSON.parse(raw);
      if (s && s.date === todayStr() && s.queue && s.queue.length) return s;
    }
  } catch (e) {}
  var ns = newState();
  saveState(ns);
  return ns;
}

function saveState(s) {
  try { localStorage.setItem(FLASH_KEY, JSON.stringify(s)); } catch (e) {}
}

/* ------------------------------------------------------------
   标记一张卡（result: 'remembered' | 'forgot'）
   未记住 → 该卡累计未记住次数 +1（同 id 副本同步），
           副本塞回队尾当天重现（round+1）
   ------------------------------------------------------------ */
function markCard(state, key, result) {
  if (state.marked[key]) return; // 防重复标记（规则：已答卡不重复操作）
  state.marked[key] = result;
  if (!state.markedTime) state.markedTime = {};
  state.markedTime[key] = Date.now();  /* 标记时间戳（薄弱 TOP5 同次数按最近未记住时间排序，PM 2026-09-07） */

  var el = null;
  for (var i = 0; i < state.queue.length; i++) {
    if (state.queue[i].key === key) { el = state.queue[i]; break; }
  }
  if (!el || result !== 'forgot') return;

  var nf = (el.forgotCount || 0) + 1;
  var maxRound = 1;
  for (var j = 0; j < state.queue.length; j++) {
    var x = state.queue[j];
    if (x.id === el.id) {
      x.forgotCount = nf;          // 同 id 累计次数同步（顽固判定口径）
      if ((x.round || 1) > maxRound) maxRound = x.round || 1;
    }
  }
  state.queue.push({
    key: el.id + '#' + (maxRound + 1),
    id: el.id,
    chapter: el.chapter,
    sub: el.sub,
    topic: el.topic,
    point: el.point,
    question: el.question,
    answer: el.answer,
    analysis: el.analysis,
    forgotCount: nf,
    round: maxRound + 1
  });
}

/* ------------------------------------------------------------
   统计（当日口径）
   done/total/remaining 按配额（演示 = 卡池 12 张，真实环境 = 350）
   stubborn = 累计未记住 ≥3 的卡（id 去重）
   ------------------------------------------------------------ */
function calcStats(state) {
  var remembered = 0, forgot = 0;
  for (var i = 0; i < state.queue.length; i++) {
    var x = state.queue[i];
    if (state.marked[x.key] === 'remembered') remembered++;
    else if (state.marked[x.key] === 'forgot') forgot++;
  }
  var done = remembered + forgot;
  var forgotMap = {};
  for (var j = 0; j < state.queue.length; j++) forgotMap[state.queue[j].id] = state.queue[j].forgotCount || 0;
  var stubborn = 0, counted = {};
  for (var id in forgotMap) {
    if (forgotMap.hasOwnProperty(id) && !counted[id] && forgotMap[id] >= 3) {
      stubborn++;
      counted[id] = true;
    }
  }
  return {
    remembered: remembered,
    forgot: forgot,
    stubborn: stubborn,
    done: done,
    total: state.quota || 0,
    remaining: Math.max((state.quota || 0) - done, 0)
  };
}

/* 针对过滤后的队列计算统计 */
function calcStatsFiltered(baseState, queue) {
  var remembered = 0, forgot = 0;
  for (var i = 0; i < queue.length; i++) {
    var x = queue[i];
    if (baseState.marked[x.key] === 'remembered') remembered++;
    else if (baseState.marked[x.key] === 'forgot') forgot++;
  }
  var done = remembered + forgot;
  return {
    remembered: remembered,
    forgot: forgot,
    done: done,
    total: queue.length,
    remaining: Math.max(queue.length - done, 0)
  };
}

/* 顽固卡判定（累计未记住 ≥3，规则 §2.1） */
function isStubbornCard(state, id) {
  var f = 0, found = false;
  for (var i = 0; i < state.queue.length; i++) {
    if (state.queue[i].id === id) { f = state.queue[i].forgotCount || 0; found = true; }
  }
  return found && f >= 3;
}

/* 队列中某 key 对应的卡 */
function findCard(state, key) {
  for (var i = 0; i < state.queue.length; i++) {
    if (state.queue[i].key === key) return state.queue[i];
  }
  return null;
}

/* ------------------------------------------------------------
   按章节聚合统计（一级 → 二级 → 三级 topic → 四级 point）
   四级叶子 = 同一 point 下所有卡片；无 point 时用 question 兜底
   返回 { total, right, wrong, subs: { subName: { total, right, wrong,
          topics: { topicName: { total, right, wrong,
          points: { pointName: { total, right, wrong } } } } } } }
   ------------------------------------------------------------ */
function getChapterStats(state, chapterName) {
  var stats = { total: 0, right: 0, wrong: 0, subs: {} };
  if (!state || !state.queue) return stats;
  for (var i = 0; i < state.queue.length; i++) {
    var c = state.queue[i];
    if (c.chapter !== chapterName) continue;
    var subName = c.sub || '其他';
    var topicName = c.topic || subName;
    var pointName = c.point || c.question || '未命名';

    if (!stats.subs[subName]) stats.subs[subName] = { total: 0, right: 0, wrong: 0, topics: {} };
    var sub = stats.subs[subName];
    if (!sub.topics[topicName]) sub.topics[topicName] = { total: 0, right: 0, wrong: 0, points: {} };
    var topic = sub.topics[topicName];
    if (!topic.points[pointName]) topic.points[pointName] = { total: 0, right: 0, wrong: 0 };
    var point = topic.points[pointName];

    var result = state.marked[c.key];
    point.total++;
    sub.total++;
    topic.total++;
    stats.total++;
    if (result === 'remembered') { point.right++; sub.right++; topic.right++; stats.right++; }
    else if (result === 'forgot') { point.wrong++; sub.wrong++; topic.wrong++; stats.wrong++; }
  }
  return stats;
}

/* 把演示用的章节树与真实答题统计合并：当某个四级节点名与真实状态匹配时更新 right/wrong */
function mergeRealStats(tree, stats) {
  if (!tree || !stats) return tree;
  for (var subName in tree.subs) {
    if (!stats.subs[subName]) continue;
    var subStat = stats.subs[subName];
    var subNode = tree.subs[subName];
    subNode.right = subStat.right;
    subNode.wrong = subStat.wrong;
    for (var topicName in subNode.topics) {
      if (!subStat.topics[topicName]) continue;
      var topicStat = subStat.topics[topicName];
      var topicNode = subNode.topics[topicName];
      topicNode.right = topicStat.right;
      topicNode.wrong = topicStat.wrong;
      for (var pointName in topicNode.points) {
        if (!topicStat.points[pointName]) continue;
        var pointStat = topicStat.points[pointName];
        var pointNode = topicNode.points[pointName];
        pointNode.right = pointStat.right;
        pointNode.wrong = pointStat.wrong;
      }
    }
  }
  return tree;
}

/* ------------------------------------------------------------
   背诵会话计时（用于完成页效率分析）
   ------------------------------------------------------------ */
var SESSION_START_KEY = 'flashCardSessionStart_v1';
var HISTORY_KEY = 'flashCardHistory_v1';

function startSession() {
  try {
    localStorage.setItem(SESSION_START_KEY, String(Date.now()));
  } catch (e) {}
}

function getSessionStart() {
  try {
    var v = localStorage.getItem(SESSION_START_KEY);
    if (v) return parseInt(v, 10) || 0;
  } catch (e) {}
  return 0;
}

function getSessionElapsed() {
  var s = getSessionStart();
  if (!s) return 0;
  return Math.max(0, Math.floor((Date.now() - s) / 1000));
}

function clearSessionStart() {
  try { localStorage.removeItem(SESSION_START_KEY); } catch (e) {}
}

/* ------------------------------------------------------------
   历史记录（完成页「较上次」对比）
   ------------------------------------------------------------ */
function recordHistory(record) {
  try {
    var arr = [];
    var raw = localStorage.getItem(HISTORY_KEY);
    if (raw) arr = JSON.parse(raw);
    if (!Array.isArray(arr)) arr = [];
    arr.unshift(record);
    if (arr.length > 30) arr = arr.slice(0, 30);
    localStorage.setItem(HISTORY_KEY, JSON.stringify(arr));
  } catch (e) {}
}

function getHistory() {
  try {
    var raw = localStorage.getItem(HISTORY_KEY);
    if (raw) {
      var arr = JSON.parse(raw);
      if (Array.isArray(arr)) return arr;
    }
  } catch (e) {}
  return [];
}

function getLastHistory() {
  var arr = getHistory();
  return arr.length ? arr[0] : null;
}

/* ------------------------------------------------------------
   薄弱知识点 TOP N（按三级考点 topic 聚合，forgot 次数降序，
   同次数按最近一次未记住时间降序；PM 2026-09-07 改三级聚合 + 时间排序）
   ------------------------------------------------------------ */
function getWeakPoints(baseState, n) {
  n = n || 5;
  var map = {};
  if (!baseState || !baseState.queue) return [];
  var mt = baseState.markedTime || {};
  for (var i = 0; i < baseState.queue.length; i++) {
    var c = baseState.queue[i];
    var key = (c.topic || c.sub || c.chapter || '未命名');   /* 三级考点聚合（无 topic 回退 sub/chapter） */
    var k2 = key + '\n' + (c.chapter || '');
    if (!map[k2]) {
      map[k2] = { name: key, chapter: c.chapter || '', sub: c.sub || '', topic: c.topic || '', wrong: 0, total: 0, lastForgot: 0 };
    }
    map[k2].total++;
    if (baseState.marked[c.key] === 'forgot') {
      map[k2].wrong++;
      var t = mt[c.key] || 0;
      if (t > map[k2].lastForgot) map[k2].lastForgot = t;   /* 该 topic 最后一次未记住时间 */
    }
  }
  var list = [];
  for (var k in map) {
    if (map.hasOwnProperty(k)) list.push(map[k]);
  }
  list.sort(function(a, b) {
    if (b.wrong !== a.wrong) return b.wrong - a.wrong;        /* 主排序：未记住次数降序 */
    return b.lastForgot - a.lastForgot;                       /* 次排序：最近未记住时间降序 */
  });
  return list.slice(0, n);
}

/* ------------------------------------------------------------
   章节掌握度分布（按 chapter 聚合 remembered / forgot / total）
   ------------------------------------------------------------ */
function getChapterDistribution(state) {
  var map = {};
  if (!state || !state.queue) return [];
  for (var i = 0; i < state.queue.length; i++) {
    var c = state.queue[i];
    var ch = c.chapter || '其他';
    if (!map[ch]) map[ch] = { name: ch, remembered: 0, forgot: 0, total: 0 };
    map[ch].total++;
    if (state.marked[c.key] === 'remembered') map[ch].remembered++;
    else if (state.marked[c.key] === 'forgot') map[ch].forgot++;
  }
  var list = [];
  for (var k in map) {
    if (map.hasOwnProperty(k)) list.push(map[k]);
  }
  list.sort(function(a, b) { return b.total - a.total; });
  return list;
}

/* ------------------------------------------------------------
   明日组成预估（规则 §1.2 补充）
   确定性回算：今日标记 → 明日到期分布，无记忆率假设
   明日复习卡 = 今日标已记住（+1天到期） + 今日标未记住（明天必现） + 顽固卡（每天必现）
   明日新卡 = max(0, 明日配额 - 明日复习卡数)；复习卡占满则无新卡
   配额基准 = 学生配置 dailyCount，钳制到卡池可用卡数内
   返回 { remembered, forgot, stubborn, fresh, quota, overflow }
   ------------------------------------------------------------ */
function calcTomorrowComposition() {
  var cfg = loadConfig();
  var daily = cfg.dailyCount || DEFAULT_CONFIG.dailyCount;
  /* 卡池收缩：配置值超过可用卡数时，实际配额 = 卡池数 */
  daily = Math.max(0, Math.min(daily, CARDS.length));

  var state = loadState();
  var queue = (state && state.queue) || [];
  var marked = (state && state.marked) || {};
  var byId = {};
  var i, x;

  /* 按卡 id 去重聚合当日标记态（副本 round 取最后 / 未记住副本覆盖） */
  for (i = 0; i < queue.length; i++) {
    x = queue[i];
    if (!byId[x.id]) byId[x.id] = { marked: false, result: null, forgotCount: x.forgotCount || 0 };
    if (marked[x.key]) {
      byId[x.id].marked = true;
      byId[x.id].result = marked[x.key];
    }
  }

  /* 三态互斥分类：顽固卡每天必现（独立一行）；今日已记住/未记住复习均排除顽固，避免重复计数 */
  var remembered = 0, forgot = 0, stubborn = 0;
  for (var id in byId) {
    if (!byId.hasOwnProperty(id)) continue;
    var b = byId[id];
    if (b.forgotCount >= 3) { stubborn++; continue; }
    if (!b.marked) continue;
    if (b.result === 'remembered') remembered++;
    else if (b.result === 'forgot') forgot++;
  }
  var review = stubborn + remembered + forgot;
  var fresh = Math.max(0, daily - review);
  var overflow = review > daily; /* 复习卡占满 → 明日无新卡，新卡顺延到后天 */

  return { remembered: remembered, forgot: forgot, stubborn: stubborn, fresh: fresh, quota: daily, overflow: overflow };
}
